package com.bank.monitor;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

// Collects the four Golden Signals for the transfer service.
public class GoldenSignals {
    // LATENCY: kept SEPARATELY for success vs failure (a fast error is still a failure).
    private final List<Long> successLatencies = new ArrayList<>();
    private final List<Long> failureLatencies = new ArrayList<>();
    private long totalRequests = 0;          // TRAFFIC basis
    private long errorRequests = 0;          // ERRORS basis
    private final double windowSeconds;

    private int poolInUse = 0;               // SATURATION basis
    private final int poolCapacity;

    public GoldenSignals(double windowSeconds, int poolCapacity) {
        this.windowSeconds = windowSeconds;
        this.poolCapacity = poolCapacity;
    }

    // Record a transfer: outcome, how long it took, and peak pool usage during it.
    public void record(boolean success, long latencyMs, int poolInUseNow) {
        totalRequests++;
        if (success) successLatencies.add(latencyMs);
        else { errorRequests++; failureLatencies.add(latencyMs); }
        this.poolInUse = Math.max(this.poolInUse, poolInUseNow);
    }

    // TRAFFIC: requests per second.
    public double trafficPerSec() { return totalRequests / windowSeconds; }

    // ERRORS: fraction of requests that failed.
    public double errorRate() {
        return totalRequests == 0 ? 0.0 : (double) errorRequests / totalRequests;
    }

    // LATENCY: p99 of SUCCESSFUL requests (the number users feel when things work).
    public long p99SuccessMs() { return percentile(successLatencies, 0.99); }
    public long p99FailureMs() { return percentile(failureLatencies, 0.99); }

    // SATURATION: how full the most constrained resource (DB pool) is.
    public double saturationPercent() { return 100.0 * poolInUse / poolCapacity; }

    private long percentile(List<Long> values, double p) {
        if (values.isEmpty()) return 0;
        List<Long> sorted = new ArrayList<>(values);
        Collections.sort(sorted);
        int idx = (int) Math.ceil(p * sorted.size()) - 1;
        return sorted.get(Math.max(0, Math.min(idx, sorted.size() - 1)));
    }
}
