package com.bank.monitor;

import java.util.logging.Logger;

// Reads the four Golden Signals and classifies overall service health.
public class SignalDashboard {
    private static final Logger log = Logger.getLogger(SignalDashboard.class.getName());

    public void report(GoldenSignals s) {
        log.info(() -> String.format("LATENCY : p99 success=%dms, p99 failure=%dms "
                + "(separated so fast errors don't hide)",
                s.p99SuccessMs(), s.p99FailureMs()));
        log.info(() -> String.format("TRAFFIC : %.1f transfers/sec", s.trafficPerSec()));
        log.info(() -> String.format("ERRORS  : %.2f%% of transfers failed", s.errorRate() * 100));
        log.info(() -> String.format("SATURATE: DB pool %.1f%% full", s.saturationPercent()));

        // Combined verdict using all four signals.
        if (s.errorRate() > 0.01)
            log.severe("HEALTH: ERRORS above 1% — users impacted, investigate now");
        if (s.p99SuccessMs() > 500)
            log.warning("HEALTH: success p99 > 500ms — slow for users even when working");
        if (s.saturationPercent() > 80)
            log.warning("HEALTH: saturation > 80% — capacity running out, scale soon (leading signal)");
        if (s.errorRate() <= 0.01 && s.p99SuccessMs() <= 500 && s.saturationPercent() <= 80)
            log.info("HEALTH: all four Golden Signals nominal — service healthy");
    }
}
