package com.bank.monitor;

import java.util.logging.*;

// Runnable demo: healthy traffic, then a saturation-driven slowdown with fast errors.
public class GoldenSignalsDemo {
    private static final Logger log = Logger.getLogger(GoldenSignalsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Golden Signals dashboard for transfer service");

        // 10-second window, DB connection pool capacity of 50.
        GoldenSignals signals = new GoldenSignals(10.0, 50);

        // 900 successful transfers, mostly fast (Rajesh->Priya etc.)
        for (int i = 0; i < 900; i++) signals.record(true, 40 + (i % 60), 20);
        // As pool saturates, 90 successes get slow (p99 climbs) at high pool usage.
        for (int i = 0; i < 90; i++) signals.record(true, 520 + (i % 80), 46);
        // 60 FAST failures (pool exhausted -> immediate reject). Fast error is still an error.
        for (int i = 0; i < 60; i++) signals.record(false, 8, 50);

        new SignalDashboard().report(signals);

        log.info("Read together: SATURATION (pool full) caused ERRORS (fast rejects) and "
               + "pushed success LATENCY up — all visible via the four signals.");
    }
}
